// ── Fibonacci: three implementations side by side ──────────────

// 1. Naive recursion — O(2^n) time
function fibNaive(n) {
  if (n <= 1) return n;
  return fibNaive(n - 1) + fibNaive(n - 2);
  // fib(40) makes ~330 million calls — takes seconds
}

// 2. Memoisation (top-down DP) — O(n) time, O(n) space
function fibMemo(n, memo = new Map()) {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n);
  const result = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, result);
  return result;
  // Each value computed exactly once; 41 calls total for fib(40)
}

// 3. Tabulation (bottom-up DP) — O(n) time, O(n) space
function fibTab(n) {
  if (n <= 1) return n;
  const dp = new Array(n + 1);
  dp[0] = 0; dp[1] = 1;
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2]; // recurrence, bottom-up
  }
  return dp[n];
}

// 4. Space-optimised tabulation — O(n) time, O(1) space
// Only need the last two values, not the full table
function fibOpt(n) {
  if (n <= 1) return n;
  let prev = 0, curr = 1;
  for (let i = 2; i <= n; i++) {
    [prev, curr] = [curr, prev + curr];
  }
  return curr;
}

console.log(fibNaive(10));  // 55  (slow for large n)
console.log(fibMemo(50));   // 12586269025
console.log(fibTab(50));    // 12586269025
console.log(fibOpt(50));    // 12586269025  — same answer, O(1) space

// ── Coin Change — unbounded (coins reusable) ──────────────────
function coinChange(coins, amount) {
  // dp[w] = min coins to make amount w; Infinity means impossible
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0; // base case

  for (let w = 1; w <= amount; w++) {
    for (const coin of coins) {
      if (coin <= w && dp[w - coin] + 1 < dp[w]) {
        dp[w] = dp[w - coin] + 1;
      }
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}

// Trace: coins=[1,5,10,25], amount=11
// dp[0]=0
// dp[1]=1  (1)
// dp[5]=1  (5)
// dp[6]=2  (5+1)
// dp[10]=1 (10)
// dp[11]=2 (10+1)
console.log(coinChange([1, 5, 10, 25], 11)); // 2
console.log(coinChange([1, 5, 10, 25], 36)); // 3  (25+10+1)
console.log(coinChange([2], 3));             // -1 (impossible)

// ── Greedy fails: DP is necessary ─────────────────────────────
// coins=[1,3,4], amount=6
// Greedy: take 4 (largest fit) -> need 2 more -> two 1s -> 3 coins total
// DP:     take 3+3 = 6 -> 2 coins total (BETTER)
console.log(coinChange([1, 3, 4], 6)); // 2  (3+3)
// Greedy always fails when coin system is not 'canonical'

// ── 0/1 Knapsack — each item used at most once ─────────────────

// Full 2D table — easier to understand
function knapsack01_2D(weights, values, capacity) {
  const n = weights.length;
  // dp[i][w] = max value using first i items, capacity w
  const dp = Array.from({ length: n + 1 }, () =>
    new Array(capacity + 1).fill(0)
  );

  for (let i = 1; i <= n; i++) {
    for (let w = 0; w <= capacity; w++) {
      // Always can skip item i
      dp[i][w] = dp[i - 1][w];
      // Take item i if it fits and improves the answer
      if (weights[i - 1] <= w) {
        dp[i][w] = Math.max(
          dp[i][w],
          values[i - 1] + dp[i - 1][w - weights[i - 1]]
        );
      }
    }
  }
  return dp[n][capacity];
}

// Space-optimised: 1D array, iterate capacity RIGHT-TO-LEFT
function knapsack01(weights, values, capacity) {
  const dp = new Array(capacity + 1).fill(0);

  for (let i = 0; i < weights.length; i++) {
    // RIGHT-TO-LEFT: ensures dp[w - weight[i]] is from PREVIOUS item
    for (let w = capacity; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], values[i] + dp[w - weights[i]]);
    }
    // If we went left-to-right, item i could be used multiple times!
  }
  return dp[capacity];
}

// items: weights=[2,3,4,5], values=[3,4,5,6], capacity=5
// Best: take items 0+1 (weight=5, value=7)
console.log(knapsack01_2D([2,3,4,5], [3,4,5,6], 5)); // 7
console.log(knapsack01([2,3,4,5], [3,4,5,6], 5));    // 7

// ── House Robber — no two adjacent houses ─────────────────────
// dp[i] = max money robbing houses 0..i
// dp[i] = max(dp[i-1], dp[i-2] + houses[i])
function rob(houses) {
  const n = houses.length;
  if (n === 0) return 0;
  if (n === 1) return houses[0];
  // Space-optimised: only need previous two values
  let prev2 = houses[0];
  let prev1 = Math.max(houses[0], houses[1]);
  for (let i = 2; i < n; i++) {
    const curr = Math.max(prev1, prev2 + houses[i]);
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}
console.log(rob([2, 7, 9, 3, 1])); // 12 (house 0 + 2 + 4 = 2+9+1)

// ── Longest Increasing Subsequence (LIS) ──────────────────────
// dp[i] = length of LIS ending at index i
// dp[i] = 1 + max(dp[j]) for all j < i where nums[j] < nums[i]
function lengthOfLIS(nums) {
  const n = nums.length;
  const dp = new Array(n).fill(1); // each element alone is LIS of length 1
  for (let i = 1; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (nums[j] < nums[i]) {
        dp[i] = Math.max(dp[i], dp[j] + 1);
      }
    }
  }
  return Math.max(...dp);
}
console.log(lengthOfLIS([10,9,2,5,3,7,101,18])); // 4 (2,3,7,18 or 2,5,7,101)

// ── Number of Ways to Reach Target Sum ────────────────────────
// Count subsets of nums that sum to target (0/1 selection)
function countSubsets(nums, target) {
  const dp = new Array(target + 1).fill(0);
  dp[0] = 1; // one way to reach sum 0: pick nothing
  for (const num of nums) {
    for (let w = target; w >= num; w--) { // right-to-left = 0/1
      dp[w] += dp[w - num];
    }
  }
  return dp[target];
}
console.log(countSubsets([1, 1, 2, 3], 4)); // 3
